function resolveOrder(graph) {
  const visited = new Set();
  const order = [];
  function visit(node) {
    if (visited.has(node)) return;
    visited.add(node);
    for (const dep of graph[node] || []) visit(dep);
    order.push(node);
  }
  for (const node in graph) visit(node);
  return order;
}

